    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("जागते सति", "सर्वस्य स्तुतिः अल्लाहस्य एव अस्ति, यः अस्मान् मृत्योः अनन्तरं जीवनं दत्तवान्, तस्य प्रति च प्रत्यागमनं भवति।", "निद्रात् जागते सति अल्लाहस्य कृतज्ञतां जानातु।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् वर्यः जागते सति इदं पठितवान्-दिनस्य आरम्भः कृतज्ञतया, परलोकस्य स्मरणेन च अभवत्।"),
        "dua_leaving_home" to DuaText("गृहात् बहिः गच्छन्", "अल्लाहस्य नाम्नः, अहं अल्लाहस्य आश्रयं करोति। अल्लाहस्य अतिरिक्तं किमपि शक्तिः, शक्तिः च नास्ति।", "गृहात् बहिः निर्गमन् अल्लाहस्य रक्षणार्थं।", "स्वर्गदूताः वदन्ति, \"त्वं मार्गदर्शितः, भवतः रक्षणं च भवति, भवतः रक्षणं च भवति\", शैतानः च दूरः भवति।"),
        "dua_anxiety_distress" to DuaText("चिन्ता-दुःखयोः निवारणं", "हे अल्लाहः, अहं भवतः आश्रयं चिन्तातः दुःखात्, असहायता अलसतात्, दुर्दशायाः, कायरताः, ऋणभारात्, जनैः वशीकृतात् च।", "दुःखस्य, चिन्तायाः, ऋणस्य, मानसिक-क्लेशस्य च समये।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः प्रायः एतत् दुआ कृतवान्-दुःखात्, अलसतायाः, ऋणस्य चिन्तायाः च आश्रयं।"),
        "dua_sayyidul_istighfar" to DuaText("सय्यद् अल्-इस्तिघफर् (क्षमायाचना प्रमुख)", "हे अल्लाहः, त्वं मम प्रभुः, त्वं विहाय पूजनीयः कश्चिद् नास्ति। त्वं माम् सृष्टवान्, अहं भवतः दासः, अहं भवतः प्रतिज्ञां च यथाशक्ति आचरामि। अहं भवतः कुकर्मात् शरणं प्रार्थयामि। अहं मम उपरि भवतः अनुग्रहं स्वीकरोमि, मम पापम् अपि स्वीकरोमि, अतः मां क्षमागृहे। त्वं विहाय अन्यत् पापम् क्षमातुं न शक्नोति।", "प्रातः सायङ्काले च-पश्चात्तापस्य सर्वोत्तमः दुआ यः पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्यनेन शिक्षितः।", "यः कश्चित् सायङ्काले निश्चयेन कथयित्वा तस्मिन् रात्रौ म्रियति सः स्वर्गं प्रविशति; प्रातःकाले उक्ते सति तथैव प्रयुज्यते।"),
        "dua_parents" to DuaText("मातापितृभ्यः प्रार्थना", "हे मम प्रभुः, मम यदा लघुवत्सरं उत्थापयितौ तथैव तौ दुदपि करुणामयि।", "मातापितृभ्यः कुरान्-द्वयः-बाल्ये तेषां परिचर्यायाः प्रतिदानरूपेण।", "ईश्वरः स्वयमेव अस्मान् पितृभ्यः एतत् दुआ कर्तुं आदिशत्।"),
        "dua_entering_mosque" to DuaText("मस्जिदं प्रविशति।", "हे अल्लाहः, मम कृते भवतः दयायाः द्वाराणि उद्घाटय।", "यदा दक्षिणपादेन मस्जिदं प्रविशति।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः मस्जिदस्य प्रवेशार्थं इदं दुआ उपदिशत्।"),
        "dua_morning_asbahna" to DuaText("प्रातःकालस्य स्मरणम्", "वयं प्रातःकाले प्रविष्टवन्तः, तथा च सर्वसाम्राज्यं प्रातःकाले प्रवेशं कृतम्। सर्वस्य स्तुतिः अल्लाहस्य एव। अल्लाहस्य विना, अन्यस्य, साङ्गीतिकस्य, पूजनीयः अधिकारः नास्ति। प्रभुत्वः तस्य एव, प्रशंसां तस्य एव, सर्वविषयेषु सः शक्तः।", "प्रातःकाले सुन्नत-दुआ पठिता।", "अल्लाहस्य सार्वभौमत्वं तस्य एकत्वं च निर्धारयित्वा दिवसस्य आरम्भः भवति।"),
        "dua_evening_amsayna" to DuaText("सायंकालस्य स्मरणम्", "वयं सायङ्काले प्रविष्टवन्तः, तथा च सर्वसाम्राज्यं अल्लाहस्य सायङ्काले प्रविष्टम्। सर्वस्य स्तुतिः अल्लाहस्य एव। अल्लाहस्य विना, अन्यस्य, साङ्गीतिकस्य, पूजनीयः अधिकारः नास्ति। प्रभुत्वः तस्य एव, प्रशंसां तस्य एव, सर्वविषयेषु च सः शक्तिमानः।", "सायङ्काले सुन्नत-दुआ पठिता।", "अल्लाहस्य सार्वभौमत्वं तस्य एकत्वं च निर्धारयित्वा रात्रेः आरम्भः भवति।"),
        "dua_bismillah_la_yadurru" to DuaText("सर्वनाशात् रक्षणम्।", "अल्लाहस्य नाम्नः, यस्य नाम्ना पृथिव्यां वा स्वर्गेषु वा किमपि हानिं कर्तुं न शक्नोति, सः सर्वश्रद्धा, सर्वज्ञः च अस्ति।", "प्रतिदिनं प्रातः सायङ्काले च त्रिवारं।", "यः कश्चित् प्रातः सायङ्काले च तिस्रवारं इमां वदति तस्य किमपि हानिः न भविष्यति।"),
        "dua_raditu_billahi" to DuaText("अल्लाहस्य प्रति सन्तुष्टः प्रभुः।", "अल्लाहः मम प्रभुः इति, इस्लाम्-मतं मम धर्मः इति, मुहम्मद्-सल्लल्लाहु-अलैहि वसल्लम्-वर्यः मम पैगम्बरः इति च इति मया प्रसन्नः।", "प्रातः सायं च त्रिवारं।", "न्यायदिने तं प्रसन्नं कर्तुं अल्लाहस्य अधिकारः भवति।"),
        "dua_hasbiyallah" to DuaText("हस्बियल्लाहः (अल्लाहः एव पर्याप्तः)", "अल्लाहः मम कृते पर्याप्तः अस्ति, तेन विना अन्यत् ईश्वरः नास्ति। अहं तेन आश्रयं स्थापयामि, सः सर्वशक्तिमत्तस्य सिंहासनस्य स्वामी।", "सप्तवारं प्रातः सायङ्काले च।", "कुरान्-ग्रन्थस्य एकः श्लोकः अस्ति-अल्लाहः एव अस्य विश्वस्य परित्यागे च चिन्तायाः निवारणम्।"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("सुभानअल्लही वा बिहम्दीही", "अल्लाहस्य स्तुतिः सर्वस्य एव।", "दिने शतशः।", "यः कश्चित् दिने शतवारं इमां वदति तस्य पापानि क्षम्यन्ते, यद्यपि ते समुद्रस्य फेणस्य सदृशाः सन्ति।"),
        "dua_tahleel_100" to DuaText("ला इलाहा इल्लल्लाहु वाहदहू", "अल्लाहः विना, यः एकलोः, साझीदारः, तस्यैवं पूजनीयः अधिकारः नास्ति। प्रभुत्वम् तस्य एव, स्तुतिः तस्यै, सर्वविषयेषु च सः अधिकारयुक्तः।", "दिने शतवारं कथयितुं महान् गुणः अस्ति।", "दश-दासान् मुक्तीकृत्य, शत-सत्क्रियाम् लिखितानि, शत-पापानि निर्मूलनानि, सायन्तर्यन्तं शैतान्-तः रक्षणं च।"),
        "dua_leaving_mosque" to DuaText("मस्जिदं त्यज्य", "हे अल्लाह, अहं तव अनुग्रहं याचये।", "यदा वामपादेन मस्जिदात् बहिः गच्छति।", "मस्जिदात् बहिः गच्छन् अल्लाहस्य अनुग्रहं, उपजीवनं च प्रार्थयतु।"),
        "dua_after_adhan" to DuaText("अधानस्य अनन्तरं", "हे अल्लाहः, अस्य परिपूर्णस्य आह्वानस्य, प्रतिष्ठिते प्रार्थनायाः च स्वामी, मुहम्मद् सल्लल्लाहु अलैहि वसिलाह् इत्येनं पुण्यम् च दानम्, तथा च तं प्रशंसिते स्थाने उत्थापयतु यत् भवान् तं प्रतिज्ञां कृतवान्।", "अधानस्य समापनेन।", "यः कश्चित् एतत् वदति सः न्यायदिने पैगम्बरस्य मध्यस्थता भविष्यति।"),
        "dua_after_salah_istighfar" to DuaText("फ़र्द सलाह् इत्यस्य अनन्तरं", "अहं अल्लाहस्य क्षमा-प्रार्थनं (3 प्रावश्यं) करोति। हे अल्लाहः, त्वं सलाम्-रूपेण तथा भवतः शान्तिः अस्ति। हे महिमावान् सम्मानवानः, त्वं धन्यः।", "सलाम् इत्यस्य अनन्तरं तत्क्षणमेव।", "प्रत्येकं अनिवार्य-प्रार्थनायाः अनन्तरं पैगम्बरः (सः) इदं पठितवान्।"),
        "dua_after_salah_help_dhikr" to DuaText("तव स्मरणे मम साहाय्यं करोतु।", "हे अल्लाहः, तव स्मरणार्थं, धन्यवादार्थं, उत्तमरूपेण भवतः पूजार्थं च मम साहाय्यं करोतु।", "प्रत्येकं प्रार्थनायाः अनन्तरं-पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् (सः) मु'दम् (र) इत्येनं वक्तुं उपदेशं दत्तवान्।", "पैगम्बरस्य विशेषोपदेशः-पूजायां उत्कृष्टता, स्थिरता च।"),
        "dua_ayatul_kursi" to DuaText("सालाह इत्यस्य अनन्तरं आयत् अल्-कुर्सी", "अल्लाहः-तस्य विना अन्यः ईश्वरः नास्ति, सः सर्वजीवनः, सर्वस्य रक्षकः अस्ति। न निद्रः, न निद्रः च तस्यै आगच्छति। आकाशमण्डले पृथिव्यां च सर्वं तस्य एव। तस्य अनुमत्या विना तस्यै मध्यस्थः कः भवितुम् अर्हति? तस्य पूर्वम्, तस्य पश्चाद् च किं भवति इति सः जानाति, तस्य ज्ञानं तस्यै न व्यापयति, तस्य कुर्शी आकाशमण्डले च व्यापिता अस्ति, तेषां रक्षणं न करोति। सः सर्वोत्तमा, महती च।", "प्रत्येकं अनिवार्य-प्रार्थनायाः अनन्तरं, निद्रात् पूर्वं च।", "यः प्रत्येकस्य अनिवार्यस्य प्रार्थनायाः अनन्तरं तस्य पठयति तस्य स्वर्गस्य च मध्ये मृत्युः इति विहाय अन्यत् किमपि न भवति; निद्रायाः पूर्वं पठितं भवति, प्रातःकालं यावत् रक्षणं प्रददाति।"),
        "dua_before_sleep" to DuaText("निद्रायाः पूर्वं", "हे अल्लाहः, तव नाम्नः अहं म्रियामि (निद्रामि), जीवामि (जागामि)।", "शयने शयनं कृत्वा।", "सः पैगम्बरः (सः) निद्रात् पूर्वं इदं पठितवान्।"),
        "dua_sleep_tasbeeh" to DuaText("निद्रायाः पूर्वं तसबीह्-ए-फ़ातिमी", "अल्लाहस्य स्तुतिः (33), सर्वस्य स्तुतिः अल्लाहस्य (33), अल्लाहः सर्वश्रेष्ठः (34)।", "निद्रायाः पूर्वं-पैगम्बरः सൽह-अल-इस्लाम् फ़ातिमा-अली (र) इत्येतयोः कृते इदं उपदिशत्।", "सः पैगम्बरः (सः) अवदत् यत् सेवकेन अपेक्षया भवतः कृते उत्तमम्।"),
        "dua_sleep_qina_adhab" to DuaText("दण्डात् रक्षणम्", "हे अल्लाहः, यः दिवसः त्वं दासान् पुनरुत्थायसि तस्मिन् दिवसे तव दण्डात् मां रक्ष।", "त्रिगुणितं, दक्षिणहस्तं गालस्य अधः स्थापयित्वा।", "निद्रां मृत्योः स्मरणरूपेण, परित्यागेः च सज्जां च करोति।"),
        "dua_bad_dream" to DuaText("दुःस्वप्नम् अनन्तरम्", "शप्तात् शयतान् इत्यतः अहं अल्लाहस्य शरणं प्रार्थये।", "दुर् स्वप्नानन्तरं वामभागे लघुतरं त्रावनं शुक्ष-थुक्, ततः अपरं प्रति तिर्यक।", "दुर्दशया भवतः हानिः न भविष्यति, तस्य विषये काचित् न वदतु।"),
        "dua_yunus" to DuaText("पैगम्बरस्य दुआ यूनुस (अ. स.)", "त्वं विहाय अन्यत् ईश्वरः नास्ति, भवतः महिमा भवेत्। अहं दुष्कृत्येषु सहभागी अभस्मि।", "तिमिष्टस्य उदरस्य पैगम्बरस्य यूनुस् (ए. एस्.) इत्यस्य दुआ-प्रत्येकस्य कष्टस्य कृते।", "यः मुस्लिमः कस्यापि विषये एतत् दुआ करोति, अल्लाहः तस्य उत्तरं ददाति।"),
        "dua_karb" to DuaText("दुःखे समये दुआ (कर्ब्)", "अल्लाहः, सर्वशक्तिमानः, सहनशीलः, अतिरिच्य अन्यत् किमपि पूजनीयं नास्ति। अल्लाहः, सर्वशक्तिमानः सिंहासनस्य स्वामी, अतिरिच्य अन्यत् किमपि पूजनीयं नास्ति। अल्लाहः, आकाशस्य स्वामी, पृथिव्याः स्वामी, सिंहासनस्य स्वामी च इति विहाय अन्यत् किमपि पूजनीयं नास्ति।", "तीव्र-कष्ट-कष्ट-काले।", "सः पैगम्बरः (सः) कष्टकाले एतत् पठितवान्।"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("या हय्यू या कय्यूम्", "हे सर्वजीवनः, हे सर्वस्य निर्वाहकः, भवतः दयया अहं साहाय्यम् अपेक्षते।", "यदा किमपि कार्यं अतीव भारकं भवति।", "यदा यदा पैगम्बरस्य किमपि व्यथितं भवति तदा सः एतत् वदति स्म।"),
        "dua_hasbunallah" to DuaText("हसबुनाल्लाहु वा निमल् वकील्", "अल्लाहः अस्माकं कृते पर्याप्तः अस्ति, सः च व्यवहारस्य उत्तमः निर्वाहकः अस्ति।", "यदा शत्रुं भयते अथवा महती बिपदाशयं सम्मुखीकरोति।", "पैगम्बरः इब्राहिम् (अ. स.) इत्येषः अग्निप्रज्वाले निक्षिप्तः तदा उक्तवान्, तथा च पैगम्बरः (स) सः अपायदौ उक्तवान्।"),
        "dua_entering_home" to DuaText("गृहं प्रविशति।", "अल्लाहस्य नाम्नम्।", "गृहे प्रवेश्य अल्लाहस्य नाम वदतु, नमस्कारं च करोतु।", "यदा अल्लाहः प्रवेशे भोजनसमये च स्मर्यते तदा शैतान् वदति यत्, अत्र भवतः निवासः, रात्रिभोजनं च नास्ति।"),
        "dua_travel" to DuaText("यात्रा हेतु दुआ (सवारी)", "यः अस्माभिः सह इमां कार्यं कृतवान् तस्य महिमा भवति, अस्माभिः स्वयमेव न शक्यते स्म, अस्माभिः प्रभोः समीपं प्रत्यागमयिष्यामः।", "वाहने उपविश्य अल्लाहू अक्बरः इति त्रिवारं उक्तवान्।", "सुन्नत-यात्रा-दुआ-रक्षणार्थं आशीर्वादार्थं च।"),
        "dua_entering_market" to DuaText("विपण्यां प्रविशतु।", "अल्लाहः विना, यः एकलोः, साझीदारः, तस्यैवं पूजनीयः अधिकारः नास्ति। तस्य आधिपत्यं तस्यै, प्रशंसापदं च। सः जीवनं ददति, मृत्युं च जनयति, सः नित्यजीवः, कदापि न म्रियति। तस्य हस्ते सर्वम् उत्तमं, सर्वविषयेषु तस्य शक्तिः अस्ति।", "यदा विपण्यां प्रविशति।", "हदीस्-ग्रन्थे तस्य महती पुरस्कारस्य (लक्षशः सत्क्रियायाः) उल्लेखः अस्ति।"),
        "dua_adam_forgiveness" to DuaText("पैगम्बर आदम (अ. स.) इत्यस्य दुआ", "हे अस्माकं प्रभुः, वयं स्वेषां अन्यायं कृतवन्तः, यदि त्वं अस्मान् क्षमातुं न दयामस्तर् तर्हि वयं निःसन्देहं क्षय्यामासु भविष्याम।", "आदम-हव्वा (ए. एस्.) इत्येतयोः पश्चात्तापस्य दुआ।", "मानवजात्याः प्रथमः पश्चात्तापः-अल्लाहः तं स्वीकृतवान्।"),
        "dua_abu_bakr" to DuaText("दुआ अबू बकर (रा.) इत्यस्मै शिक्षिता।", "हे अल्लाहः, अहं आत्मम् अत्यन्तं अन्यायम् अकरोत्, त्वं विहाय अन्यत् किमपि पापम् क्षमयति नास्ति, अतः मह्यं स्वयमेव क्षमायन्तु, मम प्रति करुणां करोतु। निःसन्देहं त्वं एव क्षमयः, दयावानः।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् अबू बक्र् अस्-सिद्दीक् (र. अ.) इत्यस्मै प्रार्थनायां (ताशाहुद् इत्यस्य अनन्तरं) वक्तुं उपदिशत्।", "प्रार्थनायाः अन्ते सुन्नत दुआ।"),
        "dua_astaghfirullah_atubu" to DuaText("दैनिकः इस्तिघफर्", "अहं अल्लाहस्य क्षमाप्रार्थनं करोमि, तस्यां प्रति पश्चात्तापम् अभ्युदयामि।", "सः पैगम्बरः दिने सप्तदशवारं अधिकं क्षमां याचयति स्म।", "सः पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् अवदत्-- अहं अल्लाहस्य क्षमा याचिद्नां, दिने सप्ततरेभ्यः अधिकतया तस्यां पश्चात्तापम् आचर्यामि।"),
        "dua_laylatul_qadr" to DuaText("दुआ-लैलात अल-कदर", "हे अल्लाहः, त्वं परमपक्वः, त्वं क्षमायितुं रोचते, अतः मां क्षमाय।", "लैलात्-अल्-कदर इत्यस्य कृते आयशा (रा) इत्यस्मै शिक्षितः।", "रमजान्-मासस्य अन्तिमरात्रौ लैलात्-अल्-कदर-इत्यस्य च कृते विशेषः दुआ।"),
        "dua_family_coolness" to DuaText("नेत्रस्य शीतलता (पति/पत्नी तथा बालकाः)", "हे अस्माकं प्रभुः, अस्माकं पत्नीभ्यः, सन्ततिभ्यः च अस्माकं नेत्रस्य शीतलतां ददातु, धार्म्मिकानां नेतृभिः सह भवतां करोतु।", "धर्मनिष्ठायाः पत्नीनां, सन्तानानां च कुरान्-दुआ।", "गृहे शान्तेः, धार्म्मिकानां च बालानां कृते।"),
        "dua_righteous_children" to DuaText("न्यायी-सन्तति-कृते", "हे मम प्रभुः, त्वं स्वयमेव मम सन्ततिम् अनुग्रहि। त्वं प्रार्थनां श्रुतवान्।", "पैगम्बरस्य ज़कारिया (अ. स.) इत्यस्य दुआ।", "बालानां अन्वेषकानां कृते कुरान्-द्वयः।"),
        "dua_ibrahim_prayer_family" to DuaText("प्रार्थना-संस्थापकाः", "हे मम प्रभुः, मम प्रार्थनां, मम सन्ततिभ्यः च स्थापयति। हे अस्माकं प्रभुः, मम प्रार्थनां स्वीकरोतु। हे अस्माकं प्रभुः, मम मातापितृभिः विश्वासिनः च क्षमिष्यति।", "पैगम्बरः इब्राहिम् (अ. स.) वर्यस्य दुआ स्वस्याः तथा तस्य वंशजाः च कृते।", "प्रायः प्रार्थनायाः अन्ते पठितम्।"),
        "dua_newlywed" to DuaText("नवविवाहितानां अभिनन्दनम्।", "अल्लाहः भवन्तं आशीर्वदाति, भवतः उपरि आशीर्वादं प्रेषयिष्यति, भवन्तौ च सद्गुणेन सङ्गृहीतुं शक्नोति।", "यदा विवाहस्य कृते कस्यापि अभिनन्दनम्।", "विवाहस्य कृते सुन्नः अभिनन्दनम्।"),
        "dua_before_eating" to DuaText("भोजनात् पूर्वं", "अल्लाहस्य नामे। (यदि विस्मृतः) अल्लाहस्य नामे, तस्य आरम्भे, अन्ते च।", "भोजनात् पूर्वं। यदि विस्मृतवान् तर्हि आंशिकरूपेण वदतु।", "बिस्मिल्ला इति वदन् शैतान् अन्नदानं कर्तुं न शक्नोति।"),
        "dua_after_eating" to DuaText("भोजनानन्तरं", "सर्वस्य प्रशंसायाः अल्लाहस्य एव, यः मम कृते एतत् पोषयित्वा मम शक्त्या वा शक्त्या वा विना तत् प्रददात्।", "भोजनस्य समाप्तेः अनन्तरं।", "यः उक्तवान् तस्य भूतकाणि पापानि क्षम्यन्ते।"),
        "dua_host" to DuaText("आतिथेयस्य कृते", "हे अल्लाहः, त्वं तान् यत् दत्तवान् तस्मिन् तेषाम् अनुग्रहिष्यस्व, तेषाम् क्षमायाचरणं करोतु, तेषाम् करुणां करोतु।", "आतिथेयस्य कृते, कस्यापि गृहे भोजनानन्तरं।", "सुन्ना-रूपेण आतिथेयस्य धन्यवादम्।"),
    )
}
